SELECT DISTINCT A.PARTY_ID id, A.PARTY_NAME text, A.PARTY_CUSTOMER_ID, A.PARTY_ID, A.PARTY_NAME FROM MST_CFETS_CUSTOMER_INFO A
(A.PARTY_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PARTY_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PARTY_CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PARTY_ID = #{initValue}

SELECT A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, A.PARTY_ID AS partyId, C.PARTY_CUSTOMER_ID AS partyCustomerId, C.PARTY_NAME AS partyName, A.CFETS_ACCT_TYPE AS cfetsAcctType, A.CREATE_USER AS createUser, A.CREATE_DEPT AS createDept, A.CREATE_TIME AS createTime, A.UPDATE_USER AS updateUser, A.UPDATE_TIME AS updateTime FROM IBU_PORTFOLIO_ACCT_RELA A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN MST_CFETS_CUSTOMER_INFO C ON A.PARTY_ID = C.PARTY_ID
AND ( A.PORTFOLIO_ID IN
null) OR A.PORTFOLIO_ID IN (
#{item}
)
AND A.PARTY_ID LIKE CONCAT('%', CONCAT(#{partyId}, '%'))

