update IBU_PORTFOLIO_ACCT_RELA
set PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR},
    PARTY_ID = #{partyId,jdbcType=VARCHAR},
    CFETS_ACCT_TYPE = #{cfetsAcctType,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where PORTFOLIO_ID = #{portfolioIdOld,jdbcType=VARCHAR}
  and PARTY_ID = #{partyIdOld,jdbcType=VARCHAR}
  and CFETS_ACCT_TYPE = #{cfetsAcctTypeOld,jdbcType=VARCHAR}

